SELECT city, rating_bucket, country_values, stddev_rating FROM (SELECT city, CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(country))) AS country_values, ROUND(STDDEV(rating), 2) AS stddev_rating FROM suppliers WHERE city = 'Bangkok' GROUP BY city, CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END) AS t WHERE stddev_rating > 23;
